#!/usr/bin/env python3
import csv
import glob
from pathlib import Path
import cv2
import numpy as np

THRESHOLD = 0.9
DEDUP_MIN_DIST = 3

TEMPLATES = {
    'coins': '/root/coin.png',
    'enemies': '/root/enemy.png',
    'turtles': '/root/turtle.png',
}


def count_objects(img, tmpl, threshold=THRESHOLD, min_dist=DEDUP_MIN_DIST):
    res = cv2.matchTemplate(img, tmpl, cv2.TM_CCOEFF_NORMED)
    ys, xs = np.where(res >= threshold)
    if len(xs) == 0:
        return 0
    scores = res[ys, xs]
    order = np.argsort(scores)[::-1]
    kept_centers = []
    h, w = tmpl.shape
    min_dist_sq = float(min_dist * min_dist)
    for idx in order:
        x = int(xs[idx])
        y = int(ys[idx])
        cx = x + w / 2.0
        cy = y + h / 2.0
        keep = True
        for kx, ky in kept_centers:
            if (cx - kx) ** 2 + (cy - ky) ** 2 <= min_dist_sq:
                keep = False
                break
        if keep:
            kept_centers.append((cx, cy))
    return len(kept_centers)


def main():
    frames = sorted(glob.glob('/root/keyframes_*.png'))
    if not frames:
        raise SystemExit('No keyframes found in /root with pattern keyframes_*.png')

    templates = {}
    for key, path in TEMPLATES.items():
        img = cv2.imread(path, cv2.IMREAD_GRAYSCALE)
        if img is None:
            raise SystemExit(f'Failed to read template: {path}')
        templates[key] = img

    rows = []
    for frame_path in frames:
        frame = cv2.imread(frame_path, cv2.IMREAD_GRAYSCALE)
        if frame is None:
            raise SystemExit(f'Failed to read frame: {frame_path}')
        counts = {}
        for key, tmpl in templates.items():
            counts[key] = count_objects(frame, tmpl)
        rows.append({
            'frame_id': frame_path,
            'coins': counts['coins'],
            'enemies': counts['enemies'],
            'turtles': counts['turtles'],
        })

    out_path = Path('/root/counting_results.csv')
    with out_path.open('w', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=['frame_id', 'coins', 'enemies', 'turtles'])
        writer.writeheader()
        writer.writerows(rows)


if __name__ == '__main__':
    main()
